import { errorText, helpText, parseArgs, parseCommaSeparatedIntegers, programNameFromArgv } from './lib/cli.mjs';
import { formatPythonList, writeLine } from './lib/format.mjs';
import { convertBits, decode, encode } from './lib/bech32/segwit.mjs';

function main() {
  const programName = programNameFromArgv(process.argv);
  const parsed = parseArgs(process.argv.slice(2));

  if (parsed.kind === 'help') {
    process.stdout.write(helpText(programName));
    process.exit(0);
  }

  if (parsed.kind === 'error') {
    process.stderr.write(errorText(programName, parsed.message));
    process.exit(2);
  }

  const data = parseCommaSeparatedIntegers(parsed.values.c);
  const converted = convertBits(data, 8, 5);
  const encoded = encode(parsed.values.a, parsed.values.b, converted);
  const decoded = decode(parsed.values.a, encoded);

  if (decoded[0] !== null && decoded[1] !== null) {
    const witver = decoded[0];
    const witprog = decoded[1];
    const convertedBack = convertBits(witprog, 5, 8);

    writeLine(formatPythonList(converted));
    writeLine(encoded);
    writeLine(String(witver));
    writeLine(formatPythonList(convertedBack));
  }
}

